package main

import (

	"fmt"
	"github.com/axiom-mesh/grid/consensus"
)

func main() {
	proofStr := `{"C_w":["","","",""],"C_b":"0x1"}`
	res := consensus.VerifyZKMLInference("57cdc5326960045c93d7c21bc76f54fe45c56cd4e66098f55a5398b4048ea460", []float64{1.0, 2.0, -1.0, 0.0}, []float64{-0.7}, proofStr, "dummy_vk", "dummy_settings")
	fmt.Println("Result:", res)

	// Additional path traversal check
	fmt.Println("Testing invalid model commitment path traversal attempt:")
	resInvalid := consensus.VerifyZKMLInference("../../../../etc/passwd", []float64{1.0}, []float64{-0.7}, proofStr, "dummy", "dummy")
	fmt.Println("Invalid commitment Result:", resInvalid)
}
